 export type PortRange = [number, number];
+
+const MAX_PORT = 65535;
+
+function parseItem(item: string): PortRange {
+  const trimmed = item.trim();
+  const rangeMatch = /^(\d+)\s*-\s*(\d+)$/.exec(trimmed);
+  if (rangeMatch) {
+    const from = Number(rangeMatch[1]);
+    const to = Number(rangeMatch[2]);
+    if (from < 1 || from > MAX_PORT || to < 1 || to > MAX_PORT) {
+      throw new Error(`port out of range in "${item}"`);
+    }
+    if (to < from) {
+      throw new Error(`range end below start in "${item}"`);
+    }
+    return [from, to];
+  }
+  if (!/^\d+$/.test(trimmed)) {
+    throw new Error(`malformed port item "${item}"`);
+  }
+  const port = Number(trimmed);
+  if (port < 1 || port > MAX_PORT) {
+    throw new Error(`port out of range in "${item}"`);
+  }
+  return [port, port];
+}

 /** Parse a port list into merged, sorted ranges. See README.md for the rules. */
 export function parsePorts(list: string): PortRange[] {
-  throw new Error("not implemented");
+  if (list.trim() === "") return [];
+  const ranges = list.split(",").map(parseItem);
+  ranges.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
+  const merged: PortRange[] = [];
+  for (const [from, to] of ranges) {
+    const last = merged[merged.length - 1];
+    if (last && from <= last[1] + 1) {
+      last[1] = Math.max(last[1], to);
+    } else {
+      merged.push([from, to]);
+    }
+  }
+  return merged;
 }

